function replaceConfirm(title,action){if(!project.walls.length&&!project.furniture.length){action();return;}modal(title,`<p>打开新方案前会先保存当前项目；保存失败时会留在当前页面。也可以先下载 JSON 备份。</p><div class="button-row"><button id="backupCurrent">先下载项目</button><button id="confirmReplace" class="primary">继续</button></div>`);$('#backupCurrent').onclick=saveProject;$('#confirmReplace').onclick=()=>{$('#modal').close();action();};}
async function loadProject(p,{savePrevious=true}={}){
 const request=++loadRequest,revision=editRevision;
 if(savePrevious&&!await persist()){
  if(request!==loadRequest)return false;
  modal('先保留当前方案',`<p>浏览器保存未成功，当前项目仍在页面中。你可以稍后重试，或下载完整 JSON 备份后再打开新方案。</p><div class="button-row"><button id="stayInProject">留在当前方案</button><button id="backupAndSwitch" class="primary">下载备份并打开新方案</button></div>`);
  $('#stayInProject').onclick=()=>$('#modal').close();$('#backupAndSwitch').onclick=async()=>{download(JSON.stringify(project,null,2),safeName()+'.json','application/json');if(await loadProject(p,{savePrevious:false})){$('#modal').close();studio?.closeHome();}};return false;
 }
 if(request!==loadRequest)return false;
 if(editRevision!==revision){toast('保存期间有新的修改，请再选择一次要打开的项目。');return false;}
 atmosphere?.exit();immersive?.exit();
 project=p;editRevision++;history=[];future=[];ui.selected=null;ui.drawStart=null;ui.measureStart=null;setTool('select');render();fitPlan(!project.nodes.length&&!!project.background);if(scene){syncScene();scene.fit();}scheduleSave();return true;
}
