$('#imageInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;const target=project;e.target.value='';if(file.size>20*1024*1024){toast('请选择小于 20 MB 的图片');return;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);}),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=data;});const scale=Math.min(1,1800/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.88);if(project!==target){toast('项目已切换，已取消图片导入');return;}mutate(()=>project.background={src,x:0,y:0,w:10000,h:10000*img.height/img.width,rotation:0,opacity:.45,visible:true,calibrated:false});showPanel('sketch');fitPlan(true);toast('底图已导入，请按已知长度校准');}catch(e){toast('无法读取该图片，请使用 JPG、PNG 或 WebP');}};
